package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Term      string   `json:"term"`
	Fields    []string `json:"fields"`
	OrderBy   string   `json:"order_by"`
	TenantID  string   `json:"tenant_id"`
}

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// buildSearchQuery constructs a product search query with tenant isolation
func buildSearchQuery(req SearchRequest) string {
	allowedFields := map[string]bool{"name": true, "sku": true, "description": true}

	var conditions []string
	conditions = append(conditions, fmt.Sprintf("tenant_id = '%s'", req.TenantID))

	for _, field := range req.Fields {
		if allowedFields[field] {
			conditions = append(conditions, fmt.Sprintf("%s ILIKE '%%%s%%'", field, req.Term))
		}
	}

	query := "SELECT id, name, price, sku FROM products WHERE " + strings.Join(conditions, " AND ")

	// Apply ordering - validated against known columns
	if req.OrderBy != "" {
		orderCol := strings.TrimSpace(req.OrderBy)
		// Note: we validate the first word only for column name
		parts := strings.SplitN(orderCol, " ", 2)
		validOrder := map[string]bool{"name": true, "price": true, "id": true, "sku": true}
		if validOrder[strings.ToLower(parts[0])] {
			query += " ORDER BY " + orderCol
		}
	}

	query += " LIMIT 50"
	return query
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid json", 400)
		return
	}

	// Tenant ID from JWT claim passed by upstream gateway
	gatewayTenant := r.Header.Get("X-Tenant-ID")
	if gatewayTenant == "" {
		http.Error(w, "unauthorized", 401)
		return
	}
	req.TenantID = gatewayTenant

	query := buildSearchQuery(req)
	log.Printf("executing query: %s", query)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("query error: %v", err)
		http.Error(w, "internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchHandler)
	http.HandleFunc("/health", healthHandler)
	log.Fatal(http.ListenAndServe(":8080", nil))
}
